import { auth } from '@/lib/auth';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import Link from 'next/link';
import { StatsCard } from '@/components/ui/stats-card';
import { Badge } from '@/components/ui/badge';
import { formatMoney, formatDate } from '@/lib/utils';

type InvoiceStatus = 'DRAFT' | 'PENDING' | 'PAID' | 'OVERDUE' | 'CANCELLED';

const statusVariant: Record<InvoiceStatus, 'neutral' | 'warning' | 'success' | 'danger'> = {
  DRAFT: 'neutral',
  PENDING: 'warning',
  PAID: 'success',
  OVERDUE: 'danger',
  CANCELLED: 'neutral',
};

export default async function AdminBillingPage() {
  const session = await auth();
  if (!session || session.user.role !== 'ADMIN') redirect('/dashboard');

  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 1);

  const [
    invoicedMonth,
    totalPaid,
    outstanding,
    retellCostMonth,
    activeUsers,
    outstandingAgg,
    paidAgg,
  ] = await Promise.all([
    prisma.invoice.aggregate({
      _sum: { total: true },
      where: { createdAt: { gte: monthStart, lt: monthEnd } },
    }),
    prisma.invoice.aggregate({
      _sum: { total: true },
      where: { status: 'PAID' },
    }),
    prisma.invoice.aggregate({
      _sum: { total: true },
      where: { status: { in: ['PENDING', 'OVERDUE'] } },
    }),
    prisma.call.aggregate({
      _sum: { totalCost: true },
      where: { startTimestamp: { gte: monthStart, lt: monthEnd } },
    }),
    prisma.user.findMany({
      where: { role: 'USER', status: 'ACTIVE' },
      orderBy: { name: 'asc' },
      include: {
        invoices: {
          orderBy: { createdAt: 'desc' },
          take: 1,
          select: { id: true, invoiceNumber: true, status: true, total: true, createdAt: true },
        },
      },
    }),
    prisma.invoice.groupBy({
      by: ['userId'],
      _sum: { total: true },
      where: { status: { in: ['PENDING', 'OVERDUE'] } },
    }),
    prisma.invoice.groupBy({
      by: ['userId'],
      _sum: { total: true },
      where: { status: 'PAID' },
    }),
  ]);

  const invoicedMonthVal = Number(invoicedMonth._sum.total ?? 0);
  const retellCost = Number(retellCostMonth._sum.totalCost ?? 0);
  const grossProfit = invoicedMonthVal - retellCost;

  const outstandingMap = new Map(outstandingAgg.map(r => [r.userId, Number(r._sum.total ?? 0)]));
  const paidMap = new Map(paidAgg.map(r => [r.userId, Number(r._sum.total ?? 0)]));

  const userRows = activeUsers.map(u => ({
    id: u.id,
    name: u.name,
    email: u.email,
    latestInvoice: u.invoices[0]
      ? {
          invoiceNumber: u.invoices[0].invoiceNumber,
          status: u.invoices[0].status as InvoiceStatus,
          total: Number(u.invoices[0].total),
          createdAt: u.invoices[0].createdAt.toISOString(),
        }
      : null,
    outstandingBalance: outstandingMap.get(u.id) ?? 0,
    totalPaidAllTime: paidMap.get(u.id) ?? 0,
  }));

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Billing</h1>
        <p className="text-gray-500 mt-1">Revenue overview and invoice management</p>
      </div>

      {/* Revenue Stats */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">This Month</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatsCard
            title="Invoiced This Month"
            value={formatMoney(invoicedMonthVal)}
            icon="dollar-sign"
          />
          <StatsCard
            title="Total Paid (All Time)"
            value={formatMoney(Number(totalPaid._sum.total ?? 0))}
            icon="check-circle"
            iconColor="text-green-600"
          />
          <StatsCard
            title="Outstanding"
            value={formatMoney(Number(outstanding._sum.total ?? 0))}
            icon="alert-circle"
            iconColor="text-yellow-500"
          />
          <StatsCard
            title="Gross Profit (Month)"
            value={formatMoney(grossProfit)}
            subtitle={`Retell cost: ${formatMoney(retellCost)}`}
            icon="trending-up"
            iconColor={grossProfit >= 0 ? 'text-green-600' : 'text-red-500'}
          />
        </div>
      </section>

      {/* Users Billing Table */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Active Users</h2>
        {userRows.length === 0 ? (
          <div className="bg-white rounded-xl border border-gray-200 p-12 text-center text-gray-400">
            No active users.
          </div>
        ) : (
          <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">User</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Outstanding</th>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Last Invoice</th>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Status</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {userRows.map(u => (
                  <tr key={u.id} className="hover:bg-gray-50">
                    <td className="px-4 py-3">
                      <p className="font-medium text-gray-900">{u.name || '—'}</p>
                      <p className="text-xs text-gray-400">{u.email}</p>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <span className={u.outstandingBalance > 0 ? 'font-medium text-yellow-600' : 'text-gray-400'}>
                        {formatMoney(u.outstandingBalance)}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      {u.latestInvoice ? (
                        <div>
                          <p className="text-gray-900">{u.latestInvoice.invoiceNumber}</p>
                          <p className="text-xs text-gray-400">{formatDate(u.latestInvoice.createdAt)} · {formatMoney(u.latestInvoice.total)}</p>
                        </div>
                      ) : (
                        <span className="text-gray-300 text-xs">No invoices</span>
                      )}
                    </td>
                    <td className="px-4 py-3">
                      {u.latestInvoice ? (
                        <Badge variant={statusVariant[u.latestInvoice.status]}>{u.latestInvoice.status}</Badge>
                      ) : (
                        <span className="text-gray-300 text-xs">—</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-right">
                      <Link
                        href={`/admin/billing/${u.id}`}
                        className="text-xs text-[#004D3E] hover:underline"
                      >
                        Manage →
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}
